import { store, type State } from '../store.ts'
import { SectionAiSettings } from './AiSettings.tsx'
import { useState } from 'preact/hooks'
import { sectionName } from '../../../shared/types.ts'
import { STUDENT_FEATURES, resolveFeatures } from '../../../shared/features.ts'
import { LabelChip } from './Labels.tsx'

export function TeachBar({ s }: { s: State }) {
  const mine = s.sections.filter((x) => s.staffIds.includes(x.id))
  const [aiFor, setAiFor] = useState<string | null>(null)
  return (
    <div class={`teachbar ${s.teach ? 'on' : ''}`}>
      <div class="row">
        <label class="switch">
          <input type="checkbox" checked={s.teach} onChange={(e) => store.setTeach((e.target as HTMLInputElement).checked)} />
          <span><strong>Teach</strong> {s.teach ? 'on: select text to label it' : 'off'}</span>
        </label>
        <label class="switch">
          <input type="checkbox" checked={s.viewAsStudent} onChange={(e) => store.setViewAsStudent((e.target as HTMLInputElement).checked)} />
          <span>View as student</span>
        </label>
      </div>
      <Switches s={s} mine={mine} />
      {s.teach && !s.viewAsStudent && <StudentFeatureSwitches mine={mine} />}
      {s.viewAsStudent && <div class="warn small">Student view: you see what a student of {s.section ? sectionName(s.section) : 'the chosen section'} sees. Switch off to teach.</div>}
      {s.teach && !s.viewAsStudent && (
        <>
          <div class="row">
            <span class="lbl">Sections</span>
            {mine.map((x) => (
              <label key={x.id} class="chk">
                <input type="checkbox" checked={s.teachSections.includes(x.id)} onChange={() => store.toggleTeachSection(x.id)} /> {sectionName(x)}
              </label>
            ))}
          </div>
          <div class="row">
            <span class="lbl">Meeting</span>
            <input type="date" value={s.meetingDate} onChange={(e) => store.setMeetingDate((e.target as HTMLInputElement).value)} />
          </div>
          <div class="row">
            <span class="lbl">On the page</span>
            <span class="small">click a checkbox beside a heading or paragraph to label it · Shift+click: current label · hover a margin line to remove · right-click a paragraph to edit its text</span>
          </div>
          <div class="row">
            <span class="lbl">Current label</span>
            {s.currentLabel && s.labels.find((l) => l.id === s.currentLabel) ? <LabelChip l={s.labels.find((l) => l.id === s.currentLabel)!} on /> : <span class="muted small">none</span>}
            <button class="link small" onClick={() => store.setView('labels')}>change</button>
            <span class="muted small">L key: the selection, or the block under the mouse</span>
          </div>
          <div class="row">
            <span class="lbl">This page</span>
            <button class="small" disabled={s.busy || !s.currentLabel} onClick={() => store.labelWholePage()}>Apply current label</button>
            <button class="small" disabled={s.busy} onClick={() => store.noteOnPage()}>Editorial note</button>
            <button class="small" onClick={() => store.openHistory('page')}>History</button>
          </div>
          <div class="row">
            <span class="lbl">Join codes</span>
            {mine.map((x) => (
              <span key={x.id} class="small">{sectionName(x)}: <code>{s.joinCodes[x.id] || '—'}</code> <button class="link small" onClick={() => store.setJoinCode(x.id, Math.random().toString(36).slice(2, 8))}>{s.joinCodes[x.id] ? 'new' : 'make'}</button></span>
            ))}
          </div>
          <div class="row">
            <label class="chk"><input type="checkbox" checked={s.showNotes} onChange={(e) => store.setShowNotes((e.target as HTMLInputElement).checked)} /> Show my editorial notes on the page</label>
            <label class="chk"><input type="checkbox" checked={s.showEdits} onChange={(e) => store.setShowEdits((e.target as HTMLInputElement).checked)} /> Show my edits in place</label>
            <label class="chk"><input type="checkbox" checked={s.showActivity} onChange={(e) => store.setShowActivity((e.target as HTMLInputElement).checked)} /> Show class activity</label>
          </div>
          <div class="row">
            <span class="lbl">Tutor</span>
            {mine.map((x) => <button key={x.id} class="small" onClick={() => setAiFor(aiFor === x.id ? null : x.id)}>{sectionName(x)}: {((x.ai as { mode?: string })?.mode) || 'off'}</button>)}
          </div>
          {aiFor && mine.find((x) => x.id === aiFor) && <SectionAiSettings s={s} section={mine.find((x) => x.id === aiFor)!} />}
          {!s.teachSections.length && <div class="warn small">Tick at least one section so coverage labels count for it.</div>}
          <div class="muted small">Projector tip: close this panel (or press \) to hide everything but the students' view.</div>
        </>
      )}
    </div>
  )
}

/** What students see, feature by feature, per section (D49). "Students see subjexts" above is the master
 *  cutoff; the tutor keeps its own settings. "→ all" copies a section's choices to every section of the book. */
function StudentFeatureSwitches({ mine }: { mine: State['sections'] }) {
  if (!mine.length) return null
  return (
    <div class="features">
      <div class="row">
        <span class="lbl">What students see</span>
        <span class="muted small">per section · off = hidden from students and not sent to their browser · you always see everything</span>
      </div>
      <table class="small features-table">
        <thead>
          <tr>
            <th></th>
            {mine.map((x) => (
              <th key={x.id}>
                {sectionName(x)}
                {mine.length > 1 && <> <button class="link small" title="Copy this section's choices to all your sections of this book" onClick={() => store.copyFeaturesToAll(x.id)}>→ all</button></>}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {STUDENT_FEATURES.map((f) => (
            <tr key={f.key}>
              <td title={`Off hides: ${f.what}`}>{f.name}{f.key === 'toc' ? <span class="muted"> (off by default)</span> : null}</td>
              {mine.map((x) => {
                const r = resolveFeatures(x.student_features)
                return (
                  <td key={x.id}>
                    <input type="checkbox" checked={r[f.key]} title={`Off hides: ${f.what}`} onChange={(e) => store.setSectionFeatures(x.id, { [f.key]: (e.target as HTMLInputElement).checked })} />
                  </td>
                )
              })}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

/** "subjexts for students" per section, the book's master switch (maintainers), and "subjexts for me" (D37). */
function Switches({ s, mine }: { s: State; mine: State['sections'] }) {
  const off = store.studentsOff()
  return (
    <div class="switches">
      <div class="row">
        <span class="lbl">Students see subjexts</span>
        {mine.map((x) => (
          <label key={x.id} class="chk" title={x.overlay_enabled ? 'On: students of this section see marks, the panel and the button' : 'Off: students of this section see the plain book, no button, no hint'}>
            <input type="checkbox" checked={x.overlay_enabled !== false} onChange={(e) => store.setSectionOverlay(x.id, (e.target as HTMLInputElement).checked)} /> {sectionName(x)}
          </label>
        ))}
        {s.isMaintainer && s.pkg && (
          <label class="chk" title="The whole book: off means nobody but signed-in staff sees anything, visitors included">
            <input type="checkbox" checked={s.pkg.students_enabled !== false} onChange={(e) => store.setPackageStudents((e.target as HTMLInputElement).checked)} /> <strong>whole book</strong>
          </label>
        )}
      </div>
      {(off.book || off.section) && <div class="warn small">{off.book ? 'The book is off for students: only staff who sign in see subjexts.' : 'Off for the ticked section(s): their students see the plain book.'} The way back in for staff on a fresh browser: Ctrl+Shift+S, or add <code>?subjexts=on</code> to the address.</div>}
      <div class="row">
        <label class="switch" title="Hide every subjexts element from your own screen except a tiny dot at the bottom right that turns it back on">
          <input type="checkbox" checked={!s.offForMe} onChange={(e) => store.setOffForMe(!(e.target as HTMLInputElement).checked)} />
          <span>subjexts for me {s.offForMe ? '(off: only the small dot shows)' : ''}</span>
        </label>
      </div>
    </div>
  )
}
