// The history of marks (D36): every creation, label change, deletion and restoration, with who and when, kept
// after the mark is gone. Shown to the mark's author and section staff only, in the panel's History view and
// under a mark card; students never see it on a page.
import { store, type State } from '../store.ts'
import type { MarkEvent } from '../../../shared/types.ts'

export function fmtWhen(iso: string): string {
  const d = new Date(iso)
  return d.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' })
}

function Names({ items }: { items: MarkEvent['labels_after'] }) {
  if (!items.length) return <span class="muted">no labels</span>
  return (
    <>
      {items.map((l, i) => (
        <span key={l.id} class="hist-label" style={{ '--c': l.color || '#9ca3af' } as Record<string, string>}>
          <span class="dot" />{l.name || 'a deleted label'}{i < items.length - 1 ? ', ' : ''}
        </span>
      ))}
    </>
  )
}

export function describeEvent(e: MarkEvent): preact.JSX.Element {
  const what = e.kind === 'label' ? 'label mark' : e.kind === 'comment' ? 'comment' : e.kind === 'author_note' ? 'editorial note' : e.kind === 'student_note' ? 'note' : e.kind
  switch (e.event) {
    case 'created': return <>Added {what}{e.labels_after.length ? <>: <Names items={e.labels_after} /></> : null}</>
    case 'labels': {
      const before = new Set(e.labels_before.map((x) => x.id))
      const after = new Set(e.labels_after.map((x) => x.id))
      const added = e.labels_after.filter((x) => !before.has(x.id))
      const removed = e.labels_before.filter((x) => !after.has(x.id))
      return <>{added.length ? <>Added <Names items={added} /></> : null}{added.length && removed.length ? '; ' : ''}{removed.length ? <>Removed <Names items={removed} /></> : null}</>
    }
    case 'deleted': return <>Removed {what}{e.labels_before.length ? <> (<Names items={e.labels_before} />)</> : null}</>
    case 'restored': return <>Restored {what}</>
    case 'anchor': return <>Re-attached {what} to moved text</>
    case 'except': {
      const before = (e.detail?.except_before || []).map((x) => x.title || x.scope)
      const after = (e.detail?.except_after || []).map((x) => x.title || x.scope)
      const added = after.filter((x) => !before.includes(x))
      const removed = before.filter((x) => !after.includes(x))
      return <>{added.length ? `Excepted ${added.join(', ')}` : ''}{added.length && removed.length ? '; ' : ''}{removed.length ? `Included ${removed.join(', ')} again` : ''}</>
    }
    default: return <>Edited {what}</>
  }
}

export function EventRow({ e, s, showWhere }: { e: MarkEvent; s: State; showWhere?: boolean }) {
  const where = e.detail?.where?.length ? e.detail.where[e.detail.where.length - 1] : ''
  const scope = e.detail?.scope === 'page' ? 'whole page' : e.detail?.scope === 'section' ? `section: ${where}` : e.detail?.scope === 'block' ? `a block in ${where}` : where ? `in ${where}` : ''
  const alive = e.mark_alive && s.marks.some((m) => m.id === e.mark_id)
  return (
    <div class={`hist ${e.event}`}>
      <div class="hist-when">{fmtWhen(e.at)}{e.actor_name && e.actor_id !== s.session?.user.id ? ` · ${e.actor_name}` : ''}</div>
      <div class="hist-what">{describeEvent(e)}</div>
      {showWhere && scope && <div class="muted small">{scope}{alive ? <> · <button class="link small" onClick={() => store.goto(e.mark_id)}>show</button></> : e.mark_alive ? '' : ' · gone'}</div>}
    </div>
  )
}

export function History({ s }: { s: State }) {
  const h = s.history
  return (
    <div class="history">
      <div class="row">
        <strong>History</strong>
        <label class="chk"><input type="radio" checked={s.historyScope === 'page'} onChange={() => store.loadHistory('page')} /> this page</label>
        <label class="chk"><input type="radio" checked={s.historyScope === 'book'} onChange={() => store.loadHistory('book')} /> whole book</label>
        <button class="small" onClick={() => store.loadHistory()} disabled={s.busy}>Refresh</button>
      </div>
      <div class="muted small">Every label added or removed, with the time, including marks since deleted. Only you (and your co-staff) see this.</div>
      {h === null && <div class="loading">Loading…</div>}
      {h && !h.length && <div class="muted pad">Nothing yet.</div>}
      {h && h.map((e) => <EventRow key={e.id} e={e} s={s} showWhere />)}
    </div>
  )
}

/** The events of one mark, under its card. */
export function MarkHistory({ s, markId }: { s: State; markId: string }) {
  const items = (s.history || []).filter((e) => e.mark_id === markId)
  if (s.history === null) return <div class="muted small">Loading history…</div>
  if (!items.length) return <div class="muted small">No history recorded (made before history was kept).</div>
  return <div class="hist-list">{items.map((e) => <EventRow key={e.id} e={e} s={s} />)}</div>
}
