// A page's address, for the links from the panel's lists (editorial notes, messages) to a passage on another page
// (docs/07-author-notes.qmd, "The notes panel"). Pure: no store, no DOM.
import type { BuildToc, TocPage } from '../../shared/types.ts'

export interface PageHrefInput {
  toc: BuildToc | null | undefined
  siteUrl: string | null | undefined     // the package's published site
  currentHref: string | null | undefined // the book page the panel is in
  currentPath: string | null | undefined // that page's path under the site (hello.path)
}

/** The page's entry in the last scan, or undefined. */
export function tocPage(toc: BuildToc | null | undefined, page: string | null | undefined): TocPage | undefined {
  return page ? toc?.pages?.find((p) => p.page === page) : undefined
}

/** The page's title, else its id, else "whole book". */
export function pageTitle(toc: BuildToc | null | undefined, page: string | null | undefined): string {
  return tocPage(toc, page)?.title || page || 'whole book'
}

/**
 * The base the book's pages hang under. The published site when the current page is on it; otherwise (a
 * localhost preview, another copy) the current address minus the current page's own path, so a jump stays
 * on the copy being read. The same rule as the page script's label table of contents (overlay/src/boot.ts).
 */
export function pageBase(i: Omit<PageHrefInput, 'toc'>): string {
  const site = (i.siteUrl || '').replace(/\/?$/, '/')
  const href = (i.currentHref || '').split(/[?#]/)[0]
  if (!href) return site
  if (site !== '/' && href.startsWith(site)) return site
  const own = (i.currentPath || '').replace(/^\//, '')
  if (own && href.endsWith(own)) return href.slice(0, href.length - own.length)
  return site !== '/' ? site : href.slice(0, href.lastIndexOf('/') + 1)
}

/**
 * The address that opens a mark's page and jumps to the mark: base + the page's path + `#yrS4=<id>`, plus
 * `&yrS4-tab=notes` when the panel should reopen on the editorial notes tab. Null when the page is not in the
 * last scan (the link would go nowhere).
 */
export function pageHref(i: PageHrefInput, page: string | null | undefined, markId: string, tab?: 'notes'): string | null {
  const p = tocPage(i.toc, page)
  if (!p) return null
  const base = pageBase(i)
  if (!base) return null
  return `${base}${p.path.replace(/^\//, '')}#yrS4=${markId}${tab ? `&yrS4-tab=${tab}` : ''}`
}
