// Which package and page this frame serves, and whether the embedding origin may (docs/03-architecture.qmd).
import type { PackageRow } from '../../shared/types.ts'

export function isLocalhost(origin: string): boolean {
  try {
    const h = new URL(origin).hostname
    return h === 'localhost' || h === '127.0.0.1' || h === '[::1]' || h.endsWith('.localhost')
  } catch {
    return false
  }
}

/** The page's origin is registered for the package, or it's a preview on localhost (allowed for anyone to read;
 *  writes on localhost are allowed only for maintainers and section staff, which RLS enforces anyway). */
export function originAllowed(pkg: PackageRow, pageOrigin: string): boolean {
  if (pkg.origins.includes(pageOrigin)) return true
  if (pkg.site_url) {
    try {
      if (new URL(pkg.site_url).origin === pageOrigin) return true
    } catch { /* ignore */ }
  }
  return isLocalhost(pageOrigin)
}
