// The Editorial notes tab: my open editorial notes (private notes to the author, kind author_note) and my in-place
// edits on this package, this page first (docs/07-author-notes.qmd). Each card links to its passage: on this page it
// scrolls and flashes; on another page it opens that page, which jumps and reopens this tab.
import { useEffect, useState } from 'preact/hooks'
import { store, type State } from '../store.ts'
import * as api from '../api.ts'
import type { BuildToc, MarkRow } from '../../../shared/types.ts'
import { whereText } from './PageMarks.tsx'
import { Md } from './Md.tsx'
import { buildPacket } from '../features/packet.ts'
import { pageHref, pageTitle } from '../pages.ts'

export const NOTES_HINT = 'Your private notes on the book\'s text, and your in-place edits. Export them as a packet; the AI applies it to the book\'s source.'

/** The card's first line: what kind of entry, its priority, its status. */
/** What `yrS4 notes resolve` saves on an applied note: the AI's feedback (docs/07-author-notes.qmd). */
export interface Applied { when?: string; by?: string; comment?: string; files?: string[]; change?: string; commit?: string }
export interface Review { state: 'accepted' | 'redo'; comment?: string; at?: string }
export interface RunInfo { id: string; index?: number; total?: number; state: 'queued' | 'in-progress' | 'applied' | 'needs-author' | 'skipped'; at?: string }
export function isApplied(x: unknown): x is Applied {
  return !!x && typeof x === 'object' && ('comment' in x || 'files' in x || 'change' in x)
}
const RUN_WORDS: Record<RunInfo['state'], string> = { queued: 'queued', 'in-progress': 'in progress', applied: 'applied', 'needs-author': 'asking', skipped: 'skipped' }
const fmtDay = (iso?: string) => (iso ? new Date(iso).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : '')
/** "Nov 3 (aiasd-week10.yml)": the provenance of a row made by `yrS4 teach` (D47); shown to its author only. */
const fmtVia = (v: unknown) => {
  const x = (v || {}) as { at?: string; packet?: string }
  return `${fmtDay(x.at)}${x.packet && x.packet !== 'command' ? ` (${x.packet})` : ''}`
}

/** The AI's feedback on an applied note (D45), and the author's verdict on it (D46). */
export function AppliedFeedback({ a, review, onReview }: { a: Applied; review?: Review; onReview?: (r: Review) => void }) {
  const [redo, setRedo] = useState<string | null>(null)
  return (
    <div class="feedback done">
      <div><b>Applied{a.by === 'ai' ? ' by the AI' : ''}{a.when ? ` · ${fmtDay(a.when)}` : ''}{a.commit ? ` · ${a.commit.slice(0, 7)}` : ''}</b>{review?.state === 'accepted' && <span class="verdict ok"> ✓ accepted{review.at ? ` ${fmtDay(review.at)}` : ''}</span>}</div>
      {a.comment && <div>{a.comment}</div>}
      {a.files && a.files.length > 0 && <div class="muted small">{a.files.join(', ')}</div>}
      {a.change && <details><summary class="small">the change</summary><pre class="change">{a.change}</pre></details>}
      {onReview && !review && redo === null && (
        <div class="actions"><button class="small" onClick={() => onReview({ state: 'accepted', at: new Date().toISOString() })}>Accept</button><button class="small" onClick={() => setRedo('')}>Redo…</button></div>
      )}
      {onReview && redo !== null && (
        <div class="redo">
          <textarea placeholder="What should be different? The AI gets this with the note." value={redo} onInput={(e) => setRedo((e.target as HTMLTextAreaElement).value)} />
          <div class="actions"><button class="small" disabled={!redo.trim()} onClick={() => { onReview({ state: 'redo', comment: redo.trim(), at: new Date().toISOString() }); setRedo(null) }}>Send back for a redo</button><button class="small" onClick={() => setRedo(null)}>Cancel</button></div>
        </div>
      )}
    </div>
  )
}

/** The AI's question on an open note, with the author's answer box (D46). */
export function QuestionBox({ question, answer, onAnswer }: { question: string; answer?: { text: string; at?: string }; onAnswer: (text: string) => void }) {
  const [text, setText] = useState('')
  return (
    <div class="feedback ask">
      <div><b>The AI asks:</b> {question}</div>
      {answer ? <div><b>Your answer:</b> {answer.text}</div> : (
        <div class="answer">
          <textarea placeholder="Your answer goes into the next packet" value={text} onInput={(e) => setText((e.target as HTMLTextAreaElement).value)} />
          <div class="actions"><button class="small" disabled={!text.trim()} onClick={() => onAnswer(text.trim())}>Send answer</button></div>
        </div>
      )}
    </div>
  )
}

/** One line for the latest AI run over the listed notes (D46). */
export function runSummary(notes: MarkRow[]): string | null {
  const runs = notes.map((m) => m.data.run as RunInfo | undefined).filter((r): r is RunInfo => !!r && !!r.id)
  if (!runs.length) return null
  const latest = runs.map((r) => r.id).sort().slice(-1)[0]
  const mine = runs.filter((r) => r.id === latest)
  const n = (st: RunInfo['state']) => mine.filter((r) => r.state === st).length
  const parts = (['applied', 'needs-author', 'in-progress', 'queued', 'skipped'] as const).filter((st) => n(st)).map((st) => `${n(st)} ${RUN_WORDS[st]}`)
  const at = mine.map((r) => r.at || '').sort().slice(-1)[0]
  return `AI run${at ? ` · ${fmtDay(at)}` : ''}: ${parts.join(', ')} of ${mine.length}`
}

export function noteHead(m: MarkRow): string {
  const status = m.status !== 'open' ? ` · ${m.status}` : ''
  if (m.kind === 'suggestion') return `in-place edit${m.data.draft && !m.body ? ' · unsaved draft' : ''}${status}`
  return `${(m.data.category as string) || 'note'} · p${m.data.priority as number}${status}`
}

export function Notes({ s }: { s: State }) {
  const [all, setAll] = useState<MarkRow[] | null>(null)
  const [toc, setToc] = useState<BuildToc | null>(null)
  const [showDone, setShowDone] = useState(false)
  const [q, setQ] = useState('')
  const [err, setErr] = useState<string | null>(null)
  const reload = () => {
    if (!s.pkg) return
    api.myNotes(s.pkg.id).then(setAll).catch((e) => setErr(String(e)))
  }
  /** Change a note's data (the author's answer or verdict) and reload the list. */
  const patch = async (m: MarkRow, data: Record<string, unknown>, status?: string) => {
    try {
      await api.updateMark(m.id, { data: { ...m.data, ...data }, ...(status ? { status } : {}) })
      reload()
    } catch (e) {
      setErr(String(e))
    }
  }
  useEffect(reload, [s.pkg?.id, s.marks.length])
  useEffect(() => { void store.toc().then(setToc).catch(() => setToc(null)) }, [s.pkg?.id])
  if (!s.pkg) return null
  if (err) return <div class="err">{err}</div>
  if (!all) return <div class="muted pad">Loading…</div>
  const page = s.hello?.page
  const order = toc?.pages?.map((p) => p.page) || []
  const rank = (m: MarkRow) => { if (m.page === page) return -1; const i = order.indexOf(m.page || ''); return i < 0 ? 1e9 : i }   // this page, then book order, then pages the scan missed
  const list = all
    .filter((m) => showDone || m.status !== 'done')
    .filter((m) => !q || (m.body || '').toLowerCase().includes(q.toLowerCase()) || whereText(m).toLowerCase().includes(q.toLowerCase()))
    .sort((a, b) => rank(a) - rank(b) || a.created_at.localeCompare(b.created_at))
  const hrefOf = (m: MarkRow) => pageHref({ toc, siteUrl: s.pkg?.site_url, currentHref: s.hello?.href, currentPath: s.hello?.path }, m.page, m.id, 'notes')
  const exportPacket = async () => {
    try {
      const build = await api.latestBuild(s.pkg!.id, true)
      const notes = all.filter((m) => m.status !== 'done' && !(m.kind === 'suggestion' && !m.body))
      const md = buildPacket(s.pkg!, build, notes)
      const stamp = new Date().toISOString().slice(0, 16).replace('T', '-').replace(':', '')
      const name = `${s.pkg!.slug.split('/')[1]}-notes-${stamp}.md`
      const blob = new Blob([md], { type: 'text/markdown' })
      const a = document.createElement('a')
      a.href = URL.createObjectURL(blob)
      a.download = name
      a.click()
      await Promise.all(notes.filter((m) => m.status === 'open').map((m) => api.updateMark(m.id, { status: 'exported' })))
      reload()
    } catch (e) {
      setErr(String(e))
    }
  }
  return (
    <div class="notes">
      <div class="muted small hint">{NOTES_HINT}</div>
      <div class="row">
        <input type="search" placeholder="Search editorial notes" value={q} onInput={(e) => setQ((e.target as HTMLInputElement).value)} />
        <label class="chk"><input type="checkbox" checked={showDone} onChange={(e) => setShowDone((e.target as HTMLInputElement).checked)} /> Show done</label>
      </div>
      <div class="row">
        <button class="small" onClick={exportPacket} disabled={!all.length}>Export editorial notes (.md)</button>
        <span class="muted small">{all.filter((m) => m.status !== 'done').length} open</span>
      </div>
      {runSummary(all) && <div class="row run"><span class="small">{runSummary(all)}</span><button class="small link" onClick={reload}>Refresh</button></div>}
      {list.map((m) => {
        const here = m.page === page
        const href = here ? null : hrefOf(m)
        return (
          <div key={m.id} class={`mark ${m.kind === 'suggestion' ? 'k-suggestion' : 'k-author_note'} ${m.status}`}>
            <div class="mark-head">
              <span class="kind">{noteHead(m)}{(m.data.run as RunInfo | undefined)?.state && <span class={`run-state st-${(m.data.run as RunInfo).state}`}> · AI: {RUN_WORDS[(m.data.run as RunInfo).state]}</span>}</span>
              <span class="muted small">{here ? 'this page' : pageTitle(toc, m.page)}</span>
            </div>
            {here ? (
              <button class="link where" title="Scroll to this passage" onClick={() => store.goto(m.id)}>{whereText(m)} <span class="goto">↓ show on page</span></button>
            ) : href ? (
              <a class="where" href={href} target="_top" title={`Open “${pageTitle(toc, m.page)}” at this passage`}>{whereText(m)} <span class="goto">↗ open page</span></a>
            ) : (
              <span class="where" title="This page is not in the last scan of the book, so there is no link to it">{whereText(m)} <span class="goto muted">(page not in the last scan)</span></span>
            )}
            {m.body && <div class="body-md"><Md text={m.body} /></div>}
            {m.data.via ? <div class="muted small">from the command line, {fmtVia(m.data.via)}</div> : null}
            {typeof m.data.question === 'string' && m.data.question && <QuestionBox question={m.data.question as string} answer={m.data.answer as { text: string; at?: string } | undefined} onAnswer={(text) => patch(m, { answer: { text, at: new Date().toISOString() } })} />}
            {isApplied(m.data.applied) && <AppliedFeedback a={m.data.applied as Applied} review={m.data.review as Review | undefined} onReview={(r) => patch(m, { review: r }, r.state === 'redo' ? 'open' : undefined)} />}
            {(m.data.review as Review | undefined)?.state === 'redo' && !isApplied(m.data.applied) && <div class="feedback ask"><b>Sent back for a redo:</b> {(m.data.review as Review).comment}</div>}
            <div class="actions">
              {here && <button class="small" onClick={() => store.edit(m)}>Edit</button>}
              {m.status !== 'done' ? <button class="small" onClick={() => store.setStatus(m, 'done')}>Done</button> : <button class="small" onClick={() => store.setStatus(m, 'open')}>Reopen</button>}
              <button class="small danger" onClick={() => { if (confirm('Delete this editorial note?')) store.remove(m.id).then(reload) }}>Delete</button>
            </div>
          </div>
        )
      })}
      {!list.length && <div class="muted pad">No editorial notes{q ? ' match' : ''}.</div>}
    </div>
  )
}
