// Build a note packet: Markdown with its own instructions, for the AI that applies the notes in the author's
// repo (docs/07-author-notes.qmd). Shared by the frame's Export button and `yrS4 notes export`.
import type { MarkRow, PackageRow, BuildToc, PageMap } from '../../../shared/types.ts'

export interface BuildLike { id: string; built_at: string; toc: BuildToc; page_map: PageMap | null }

export function buildPacket(pkg: PackageRow, build: BuildLike | null, notes: MarkRow[], opts: { local?: string; exported?: string } = {}): string {
  const exported = opts.exported || new Date().toISOString().replace(/\.\d{3}Z$/, 'Z')
  const pageMap = build?.page_map || {}
  const pages = build?.toc?.pages || []
  const site = pkg.site_url || ''
  const groups = new Map<string, MarkRow[]>()
  const order = (p: string | null) => (p ? pages.findIndex((x) => x.page === p) : 1e9)
  const sorted = [...notes].sort((a, b) => order(a.page) - order(b.page) || (a.anchor?.position?.start || 0) - (b.anchor?.position?.start || 0))
  for (const n of sorted) {
    const file = n.page ? pageMap[n.page]?.source || pageMap[n.page]?.path || n.page : '(whole book)'
    groups.set(file, [...(groups.get(file) || []), n])
  }
  const lines: string[] = []
  lines.push('---')
  lines.push('yrS4-packet: author-notes')
  lines.push(`package: ${pkg.slug}`)
  lines.push(`source_repo: ${pkg.source_repo || '(unknown)'}${opts.local ? `   # local: ${opts.local}` : ''}`)
  lines.push(`exported: ${exported}`)
  lines.push(`notes: ${notes.length}`)
  lines.push('---')
  lines.push('')
  lines.push('# Instructions for the AI applying these editorial notes')
  lines.push('')
  lines.push(`You are editing the source of the book "${pkg.title}" in the repo above. Each editorial note below was written by the author while reading the published book (an in-place edit is the author's rewrite of a block). For each note:`)
  lines.push('')
  lines.push('1. Find the passage in the given source file. Search for the quote; the rendered text may differ from the source in Markdown syntax, callout fences, shortcodes and chapter numbers. If the entry says the passage is program output, find the code cell or chunk that produces it. If the quote isn\'t in the named file, search the whole repo: it may come from an included file or a shortcode.')
  lines.push('2. Read all the notes for a file before editing it; some notes interact (moves, inserts).')
  lines.push('3. Make the change the note asks for, following the repo\'s AGENTS.md and skills.')
  lines.push('4. If a note is unclear, needs a decision from the author, or the passage can\'t be found, don\'t guess: mark it `needs-author` with a one-line question.')
  lines.push('5. A note with an "Author\'s answer" line is clear now: do what the answer says. A note with a "Reviewer: redo" line was applied once and sent back: do it again the way the reviewer says.')
  lines.push('6. Record what you did on each note: with the yrS4 CLI as you go (`yrS4 notes run note ID --state …`, the subjexts-apply-notes skill), or, if you cannot run it, write `yrS4-results.json` next to this file when done (format at the end). For each applied note give `comment` (one or two sentences on what you did and why), `files`, `change` (the diff of that change, or the new text when a diff says little, under 20,000 characters) and `commit` when you committed. The author reads these on the note in the panel, so they are the feedback. Don\'t commit on the author\'s branch: one commit per note on a branch `yrS4-notes-<date>` is the default (the repo\'s own rules may say otherwise).')
  lines.push('')
  for (const [file, ns] of groups) {
    lines.push(`## ${file}`)
    lines.push('')
    for (const n of ns) {
      const a = n.anchor_current || n.anchor
      const short = n.id.slice(0, 4)
      const cat = n.kind === 'suggestion' ? 'rewrite (in-place edit)' : (n.data.category as string) || 'note'
      const prio = n.data.priority ?? ''
      lines.push(`### N-${short} · ${cat} · priority ${prio}`)
      const path = n.page ? pageMap[n.page]?.path : undefined
      if (path) lines.push(`- Page: ${site}${path}#yrS4=${n.id}`)
      lines.push(`- Id: ${n.id}`)
      if (a?.section?.headings?.length) lines.push(`- Where: ${a.section.headings.join(' › ')}${a.scope === 'section' ? ' (whole section)' : a.scope === 'page' ? ' (whole page)' : ''}`)
      if (n.build_id) lines.push(`- Written against: ${n.build_id}${build && build.id !== n.build_id ? ` (the site has been rebuilt since: ${build.id})` : ''}`)
      if (a?.quote) lines.push(`- Passage: "…${a.quote.prefix}**[${a.quote.exact}]**${a.quote.suffix}…"`)
      if (a?.block) {
        const k = a.block.kind
        const span = a.block.kinds?.length ? ` (the passage spans blocks: ${a.block.kinds.join(', then ')})` : ''
        lines.push(`- Block: ${k}${span}${k === 'output' || a.block.kinds?.includes('output') ? ' (program output: find the code that produces it; the source file holds the code, not this text)' : ''}`)
      }
      lines.push('')
      if (n.kind === 'suggestion') {
        lines.push('> Replace this block with the proposed text below (the teacher edited it in place on the published page).')
        if (n.data.original_md) {
          lines.push('>')
          lines.push('> The block as the teacher saw it (reconstructed Markdown):')
          lines.push('>')
          for (const l of String(n.data.original_md).split('\n')) lines.push(`> ${l}`)
        }
        lines.push('>')
        lines.push('> Proposed text:')
        lines.push('>')
        for (const l of (n.body || '').split('\n')) lines.push(`> ${l}`)
      } else for (const l of (n.body || '(no text)').split('\n')) lines.push(`> ${l}`)
      if (n.data.proposed) {
        lines.push('>')
        lines.push('> Proposed text:')
        lines.push('>')
        for (const l of String(n.data.proposed).split('\n')) lines.push(`> ${l}`)
      }
      const answer = n.data.answer as { text?: string } | undefined
      if (answer?.text) {
        lines.push('')
        if (n.data.question) lines.push(`- The AI asked: ${String(n.data.question).replace(/\s+/g, ' ')}`)
        lines.push(`- Author's answer: ${answer.text.replace(/\s+/g, ' ')}`)
      }
      const review = n.data.review as { state?: string; comment?: string } | undefined
      const applied = n.data.applied as { commit?: string; files?: string[]; comment?: string } | undefined
      if (review?.state === 'redo') {
        lines.push('')
        lines.push(`- Reviewer: redo · ${(review.comment || '').replace(/\s+/g, ' ') || '(no comment)'}${applied ? ` (the earlier change: ${applied.commit ? `commit ${applied.commit.slice(0, 7)}` : (applied.files || []).join(', ') || 'see the note'}${applied.comment ? `; the AI said: ${applied.comment}` : ''})` : ''}`)
      }
      lines.push('')
    }
  }
  lines.push('## Results format')
  lines.push('```json')
  lines.push(`{"packet": "${pkg.slug.split('/')[1]}-notes-${exported}",`)
  lines.push(' "results": [{"id": "<full note id>", "status": "applied|needs-author|skipped", "comment": "what you did, or the question for the author", "files": ["…"], "change": "the diff or the new text"}]}')
  lines.push('```')
  return lines.join('\n') + '\n'
}
