// The student-facing features a section's staff can switch off one by one (docs/06a-labels.qmd "Switches",
// D49): the list, each one's default, and how a section's stored choices resolve. Shared by the frame (which
// enforces them), the page script (which draws accordingly), the CLI (`yrS4 teach features`) and the tests.
// "Students see subjexts" (sections.overlay_enabled) stays the master cutoff above all of these; the tutor has
// its own setting (sections.ai.mode).

export type StudentFeature = 'button' | 'labels' | 'toc' | 'comments' | 'messages' | 'reactions' | 'notes' | 'covered'

export interface StudentFeatureDef {
  key: StudentFeature
  name: string            // the switch's label in the Teach bar
  what: string            // what "off" hides from students
  default: boolean
}

export const STUDENT_FEATURES: StudentFeatureDef[] = [
  { key: 'button', name: 'The subjexts button and panel', what: 'the button at the bottom right, the panel behind it and the selection toolbar; lines, legend and pages still show', default: true },
  { key: 'labels', name: 'Labels and margin lines', what: 'the colored lines, the legend and the hover card (published labels stay published, students just do not see them)', default: true },
  { key: 'toc', name: 'Table of contents by label', what: 'the page and its entry in the book\'s menu', default: false },
  { key: 'comments', name: 'Comments for students', what: 'your comments on passages', default: true },
  { key: 'messages', name: 'Ask my instructor', what: 'the toolbar button and the message form', default: true },
  { key: 'reactions', name: 'Reactions', what: '"This helped", "I don\'t understand" and the class-activity counts', default: true },
  { key: 'notes', name: 'Highlights and private notes', what: 'a student\'s own highlights and notes', default: true },
  { key: 'covered', name: 'What we covered', what: 'the link to the by-meeting page', default: true },
]

export type StudentFeatures = Record<StudentFeature, boolean>
/** What a section stores: only the features that differ from nothing in particular; absent = the default. */
export type StoredFeatures = Partial<Record<StudentFeature, boolean>>

export const FEATURE_KEYS = STUDENT_FEATURES.map((f) => f.key)
export function isFeature(k: string): k is StudentFeature {
  return (FEATURE_KEYS as string[]).includes(k)
}

/** A section's choices with the defaults filled in. Unknown keys are ignored. */
export function resolveFeatures(stored: StoredFeatures | null | undefined): StudentFeatures {
  const out = {} as StudentFeatures
  for (const f of STUDENT_FEATURES) {
    const v = stored?.[f.key]
    out[f.key] = typeof v === 'boolean' ? v : f.default
  }
  return out
}

/** Everything on (staff), or everything off. */
export function allFeatures(on: boolean): StudentFeatures {
  const out = {} as StudentFeatures
  for (const f of STUDENT_FEATURES) out[f.key] = on
  return out
}

/** What a viewer gets from several sections: a feature is on when any of them has it on (a visitor who chose
 *  no section sees what any public section of the book allows). No sections: the defaults. */
export function unionFeatures(sections: Array<StoredFeatures | null | undefined>): StudentFeatures {
  if (!sections.length) return resolveFeatures(null)
  const out = allFeatures(false)
  for (const s of sections) {
    const r = resolveFeatures(s)
    for (const k of FEATURE_KEYS) if (r[k]) out[k] = true
  }
  return out
}
