// The labels the right-click menu offers (D50, docs/06a-labels.qmd "The right-click menu"): the pinned ones first,
// in the order they were pinned, then the most recently used of the rest, up to `recent`. A label used for the
// first time goes to the front of the recent list, so the oldest one of the `recent` drops out of the menu.
import type { LabelInfo } from '../../shared/types.ts'

export interface MenuRules {
  recent: number        // how many of the most recently used labels the menu shows (besides the pinned ones)
  pinned: string[]      // label ids that are always in the menu, in this order
}
export const MENU_DEFAULTS: MenuRules = { recent: 7, pinned: [] }
export const MENU_RECENT_MAX = 20

/** `labels` is the viewer's list, most recently used first (store.labelInfos()); only their own labels are offered. */
export function menuLabelIds(labels: LabelInfo[], rules: MenuRules): string[] {
  const mine = labels.filter((l) => l.mine)
  const pinned = rules.pinned.filter((id) => mine.some((l) => l.id === id))
  const n = Math.max(0, Math.min(MENU_RECENT_MAX, Math.floor(rules.recent) || 0))
  const recent = mine.map((l) => l.id).filter((id) => !pinned.includes(id)).slice(0, n)
  return [...pinned, ...recent]
}

/** The rules as saved in the browser (localStorage `yrS4-menu`): missing or broken parts fall back to the defaults. */
export function readMenuRules(raw: string | null): MenuRules {
  try {
    const p = JSON.parse(raw || '{}') as Partial<MenuRules>
    const recent = typeof p.recent === 'number' && Number.isFinite(p.recent) ? Math.max(0, Math.min(MENU_RECENT_MAX, Math.floor(p.recent))) : MENU_DEFAULTS.recent
    const pinned = Array.isArray(p.pinned) ? p.pinned.filter((x): x is string => typeof x === 'string') : []
    return { recent, pinned }
  } catch {
    return { ...MENU_DEFAULTS }
  }
}
